def main():
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    output_path = os.path.join(base_dir, "LEADS_BATCH_3.csv")
    fieldnames = [
        "id", "business_name", "country", "city", "maps_profile",
        "website_status", "social", "contact", "owner", "why_need_website", "quality"
    ]
    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(LEADS)
    print(f"Wrote {len(LEADS)} verified leads to {output_path}")

if __name__ == "__main__":
    main()
